/* ===================================================================
 * Per-channel packet inlet buffer
 * ===================================================================
 * Each channel holds at most one packet at a time.
 * TODO: this can be significantly improved if Hal provides
 * a better semaphore implementation with:
 * -timeouts
 * -initialization value (so a true semaphore instead of a mutex)
 * -release being a defined behaviour in a non-owner thread
 *    (true semaphore instead of a mutes)\
 * Optional signalling via events provided via Hal would be a help.
 * The current implementation is to demonstrate the working principle.
 * =================================================================== */

typedef struct
{
   asn1SccOBCP_Packet packet;
   /* Synchronises producer (PI_receive_packet) and consumer (wrapper_receive_packet).
    * Producer: store payload, then atomic_store(..., memory_order_release).
    * Consumer: atomic_load(..., memory_order_acquire), then read payload.
    * This acquire-release pair provides the necessary memory barrier on both
    * x86 (compiler fence) and ARM (stlr/ldar or stl/lda instructions). */
   atomic_bool occupied;
} OBCP_PacketChannel;

static OBCP_PacketChannel packet_channels[OBCP_PACKET_CHANNEL_COUNT];

static bool obcp_code_is_precompiled_mpy(const asn1SccOBCP_Code *code)
{
   return code->nCount >= 2 &&
          (uint8_t)code->arr[0] == OBCP_MPY_MAGIC_NUMBER &&
          (uint8_t)code->arr[1] == MPY_VERSION;
}

static inline int32_t get_worker_id_by_pid(const asn1SccPID pid)
{
   for (int32_t id = 0; id < (int32_t)workers_count; id++)
   {
      if (workers[id].pid == pid)
      {
         return id;
      }
   }
   return -1;
}

static inline void clear_obcp(const uint32_t id)
{
   /* Relaxed: clear_obcp is only called while the engine mutex is held (or
    * during single-threaded startup) and no concurrent worker can observe
    * the slot after it has been cleared. */
   atomic_store_explicit(&obcps[id].loaded, false, memory_order_relaxed);
   obcps[id].code.nCount = 0;
   /* Relaxed ordering is sufficient here: clear_obcp is only called while the
    * engine mutex is held (or during single-threaded startup), so no concurrent
    * reader can observe these stores out-of-order. */
   atomic_store_explicit(&obcps[id].status, OBCP_Execution_Status_inactive, memory_order_relaxed);
   atomic_store_explicit(&obcps[id].current_step, OBCP_NO_STEP, memory_order_relaxed);
   atomic_store_explicit(&obcps[id].abort_requested, false, memory_order_relaxed);
   atomic_store_explicit(&obcps[id].stop_requested, false, memory_order_relaxed);
   atomic_store_explicit(&obcps[id].stop_at_step, 0u, memory_order_relaxed);
}

static inline void clear_engine()
{
   obcps_count = 0;
   for (uint32_t i = 0; i < OBCP_MAXIMUM_NUMBER_OF_LOADED_OBCPS; i++)
   {
      clear_obcp(i);
   }
   workers_count = 0;
   for (uint32_t i = 0; i < OBCP_MAXIMUM_NUMBER_OF_REGISTERED_OBCP_WORKERS; i++)
   {
      workers[i].registered = 0;
      workers[i].used = 0;
   }
}

