/* Returns the obcps[] index for the OBCP running in the calling thread,
 * or -1 if no OBCP index has been stored in TLS for this thread. */
static int32_t get_current_obcp_index_for_thread(void)
{
   return (int32_t)obcp_engine_tls_get(obcp_thread_local_value_index_obcp_index) - 1;
}

/* Raise a MicroPython exception if the current OBCP has been aborted.
 * Called at the entry of every user-facing wrapper. */
static void check_abort(void)
{
   const int32_t obcp_idx = get_current_obcp_index_for_thread();
   if (obcp_idx >= 0 && atomic_load_explicit(&obcps[obcp_idx].abort_requested, memory_order_acquire))
   {
      mp_raise_msg(&mp_type_Exception, MP_ERROR_TEXT("OBCP aborted"));
   }
}

/* Wrapper for beginstep: record that step `id` has started. */
static bool wrapper_beginstep(const uint32_t id)
{
   check_abort();
   const int32_t obcp_idx = get_current_obcp_index_for_thread();
   if (obcp_idx < 0)
   {
      return false;
   }
   /* Release: ensures PI_get_obcp_status (acquire) sees the updated step id. */
   atomic_store_explicit(&obcps[obcp_idx].current_step, id, memory_order_release);
   return true;
}

/* Wrapper for endstep: verify `id` matches the begun step, then clear it.
 * Returns false (causing a MicroPython RuntimeError) on mismatch. */
static bool wrapper_endstep(const uint32_t id, const bool success)
{
   check_abort();
   (void)success; /* success is informational; mismatch is the only hard error */
   const int32_t obcp_idx = get_current_obcp_index_for_thread();
   if (obcp_idx < 0)
   {
      return false;
   }
   /* Relaxed: same thread wrote current_step in wrapper_beginstep. */
   if (atomic_load_explicit(&obcps[obcp_idx].current_step, memory_order_relaxed) != id)
   {
      return false;
   }
   /* Release: ensures PI_get_obcp_status (acquire) sees OBCP_NO_STEP. */
   atomic_store_explicit(&obcps[obcp_idx].current_step, OBCP_NO_STEP, memory_order_release);
   /* Acquire on stop_requested: pairs with the release store in PI_stop_obcp,
    * guaranteeing that stop_at_step is visible before we read it below.
    * stop_at_step is read once into a local variable to avoid a TOCTOU
    * race: PI_stop_obcp (Protected) can overwrite stop_at_step between two
    * separate relaxed loads, producing inconsistent stop-at logic. */
   if (atomic_load_explicit(&obcps[obcp_idx].stop_requested, memory_order_acquire))
   {
      const uint32_t step_to_stop_at = atomic_load_explicit(&obcps[obcp_idx].stop_at_step, memory_order_relaxed);
      if (step_to_stop_at == 0u || step_to_stop_at == id)
      {
         mp_raise_msg(&mp_type_Exception, MP_ERROR_TEXT("OBCP stopped"));
      }
   }
   return true;
}

